        assert_equal(func(&#x27;&#x27;, &#x27;foo&#x27;), False)
        assert_equal(func(&#x27;Nib&#x27;, &#x27;bin&#x27;), False)
        assert_equal(func(&#x27;act&#x27;, &#x27;cat&#x27;), True)
        assert_equal(func(&#x27;a ct&#x27;, &#x27;ca t&#x27;), True)
