Array-backed priority queue Stacks & queues    Problem: Implement a priority queue backed by an array.    Constraints   Do we expect the methods to be insert, extract_min, and decrease_key?   Yes   Can we assume there aren&#x27;t any duplicate keys?   Yes   Do we need to validate inputs?   No   Can we assume this fits memory?   Yes    insert   insert general case -&gt; inserted node   extract_min   extract_min from an empty list -&gt; None  extract_min general case -&gt; min node   decrease_key   decrease_key an invalid key -&gt; None  decrease_key general case -&gt; updated node   insert   Append to the internal array.   Complexity:   Time: O(1)  Space: O(1)   extract_min   Loop through each item in the internal array   Update the min value as needed   Remove the min element from the array and return it   Complexity:   Time: O(n)  Space: O(1)   decrease_key   Loop through each item in the internal array to find the matching input   Update the matching element&#x27;s key    Complexity:   Time: O(n)  Space: O(1)   Code   %%writefile priority_queue.py
import sys


class PriorityQueueNode(object):

    def __init__(self, obj, key):
        self.obj = obj
        self.key = key

    def __repr__(self):
        return str(self.obj) + &#x27;: &#x27; + str(self.key)


class PriorityQueue(object):

    def __init__(self):
        self.array = []

    def __len__(self):
        return len(self.array)

    def insert(self, node):
        self.array.append(node)
        return self.array[-1]

    def extract_min(self):
        if not self.array:
            return None
        minimum = sys.maxsize
        for index, node in enumerate(self.array):
            if node.key &lt; minimum:
                minimum = node.key
                minimum_index = index
        return self.array.pop(minimum_index)

    def decrease_key(self, obj, new_key):
        for node in self.array:
            if node.obj is obj:
                node.key = new_key
                return node
        return None   Unit Test   %%writefile test_priority_queue.py
from nose.tools import assert_equal


class TestPriorityQueue(object):

    def test_priority_queue(self):
        priority_queue = PriorityQueue()
        assert_equal(priority_queue.extract_min(), None)
        priority_queue.insert(PriorityQueueNode(&#x27;a&#x27;, 20))
        priority_queue.insert(PriorityQueueNode(&#x27;b&#x27;, 5))
        priority_queue.insert(PriorityQueueNode(&#x27;c&#x27;, 15))
        priority_queue.insert(PriorityQueueNode(&#x27;d&#x27;, 22))
        priority_queue.insert(PriorityQueueNode(&#x27;e&#x27;, 40))
        priority_queue.insert(PriorityQueueNode(&#x27;f&#x27;, 3))
        priority_queue.decrease_key(&#x27;f&#x27;, 2)
        priority_queue.decrease_key(&#x27;a&#x27;, 19)
        mins = []
        while priority_queue.array:
            mins.append(priority_queue.extract_min().key)
        assert_equal(mins, [2, 5, 15, 19, 22, 40])
        print(&#x27;Success: test_min_heap&#x27;)


def main():
    test = TestPriorityQueue()
    test.test_priority_queue()


if __name__ == &#x27;__main__&#x27;:
    main()

