class TwoStackQueue {
  constructor() { this.incoming = []; this.outgoing = []; }
  enqueue(value) {
    if (value == null) throw new TypeError('Non-null value required');
    this.incoming.push(value);
  }
  dequeue() {
    if (!this.outgoing.length) while (this.incoming.length) this.outgoing.push(this.incoming.pop());
    return this.outgoing.length ? this.outgoing.pop() : null;
  }
}

