class TreeNode {
  constructor(data, left = null, right = null) {
    this.data = data; this.left = left; this.right = right; this.parent = null;
    if (left) left.parent = this;
    if (right) right.parent = this;
  }
  insert(value) {
    let node = this;
    while (true) {
      const side = value <= node.data ? "left" : "right";
      if (node[side]) node = node[side];
      else { node[side] = new TreeNode(value); node[side].parent = node; return node[side]; }
    }
  }
}

class BinarySearchTree {
  constructor() { this.root = null; }
  insert(value) {
    if (value == null) throw new TypeError('Non-null value required');
    if (!this.root) { this.root = new TreeNode(value); return this.root; }
    return this.root.insert(value);
  }
}

