            Dependency(&#x27;f&#x27;, &#x27;c&#x27;),
            Dependency(&#x27;f&#x27;, &#x27;b&#x27;),
            Dependency(&#x27;f&#x27;, &#x27;a&#x27;),
            Dependency(&#x27;c&#x27;, &#x27;a&#x27;),
            Dependency(&#x27;b&#x27;, &#x27;a&#x27;),
            Dependency(&#x27;a&#x27;, &#x27;e&#x27;),
