      const p = Math.floor((i - 1) / 2);
      if (this.compare(a[p], a[i]) <= 0) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  extractMin() {
    const a = this.items;
    if (!a.length) return null;
    const result = a[0], last = a.pop();
    if (!a.length) return result;
    a[0] = last; let i = 0;
    while (true) {
      let best = i;
      const left = 2 * i + 1, right = left + 1;
      if (left < a.length && this.compare(a[left], a[best]) < 0) best = left;
      if (right < a.length && this.compare(a[right], a[best]) < 0) best = right;
      if (best === i) break;
      [a[i], a[best]] = [a[best], a[i]]; i = best;
    }
    return result;
  }
}

function shortestWeightedPath(graph, start, end) {
  if (!graph || !graph.edges.has(start) || !graph.edges.has(end)) throw new TypeError('Existing vertices required');
  const distance = new Map([[start, 0]]), previous = new Map(), heap = new MinHeap((a,b) => a.cost-b.cost);
  heap.insert({key: start, cost: 0});
  while (heap.items.length) {
    const {key, cost} = heap.extractMin();
    if (cost !== distance.get(key)) continue;
    if (key === end) {
      const path = []; for (let cur = end; cur !== undefined; cur = previous.get(cur)) path.push(cur);
      return {path: path.reverse(), distance: cost};
    }
    for (const [next, weight] of graph.edges.get(key)) {
      const candidate = cost + weight;
      if (candidate < (distance.get(next) ?? Infinity)) {
        distance.set(next, candidate); previous.set(next, key); heap.insert({key: next, cost: candidate});
      }
    }
  }
  return null;
}

