function lowestCommonAncestor(root, a, b) {
  if (!root || !a || !b) return null;
  function contains(node, target) {
    return !!node && (node === target || contains(node.left,target) || contains(node.right,target));
  }
  if (!contains(root,a) || !contains(root,b)) return null;
  function lca(node) {
    if (!node || node === a || node === b) return node;
    const left=lca(node.left), right=lca(node.right);
    return left && right ? node : left ?? right;
  }
  return lca(root);
}

