class TrieNode {
  constructor() { this.children=new Map(); this.terminal=false; }
}
class Trie {
  constructor() { this.root=new TrieNode(); }
  insert(word) {
    let node=this.root;
    for (const ch of word) { if (!node.children.has(ch)) node.children.set(ch,new TrieNode()); node=node.children.get(ch); }
    node.terminal=true;
  }
  find(word) {
    let node=this.root;
    for (const ch of word) { node=node.children.get(ch); if (!node) return false; }
    return node.terminal;
  }
  remove(word) {
    let node=this.root; const path=[];
    for (const ch of word) { path.push([node,ch]); node=node.children.get(ch); if (!node) return false; }
    if (!node.terminal) return false;
    node.terminal=false;
    for (let i=path.length-1;i>=0 && !node.terminal && !node.children.size;i--) {
      const [parent,ch]=path[i]; parent.children.delete(ch); node=parent;
    }
    return true;
  }
  listWords() {
    const words=[], path=[];
    function walk(node) {
      if (node.terminal) words.push(path.join(''));
      for (const [ch,child] of node.children) { path.push(ch); walk(child); path.pop(); }
    }
    walk(this.root); return words;
  }
}

