class Bits {
  constructor(number) {
    if (typeof number !== 'bigint') throw new TypeError('Use a BigInt, for example 13n');
    this.number=number;
  }
  index(i) { if (!Number.isInteger(i) || i < 0) throw new RangeError('Nonnegative bit index required'); return BigInt(i); }
  getBit(i) { return (this.number & (1n << this.index(i))) !== 0n; }
  setBit(i) { return this.number |= 1n << this.index(i); }
  clearBit(i) { return this.number &= ~(1n << this.index(i)); }
  clearBitsMsbToIndex(i) { return this.number &= (1n << this.index(i)) - 1n; }
  clearBitsIndexToLsb(i) { return this.number &= ~((1n << (this.index(i) + 1n)) - 1n); }
  updateBit(i, value) {
    if (value !== 0 && value !== 1) throw new TypeError('Bit must be 0 or 1');
    return value === 1 ? this.setBit(i) : this.clearBit(i);
  }
}

