function drawLine(screen, width, x1, x2) {
  if (!screen || !screen.length || !Number.isInteger(width) || width <= 0 || width % 8 !== 0 ||
      (screen.length * 8) % width !== 0 || !Number.isInteger(x1) || !Number.isInteger(x2) ||
      x1 < 0 || x2 < x1 || x2 >= screen.length * 8 || Math.floor(x1 / width) !== Math.floor(x2 / width)) {
    throw new RangeError('Valid screen and endpoints in one row required');
  }
  for (let pixel=x1;pixel<=x2;pixel++) screen[Math.floor(pixel/8)] |= 1 << (7 - pixel % 8);
  return screen;
}

