function longestOnesAfterFlip(number) {
  if (!Number.isInteger(number) || number < 0 || number > 0xffffffff) throw new RangeError('Unsigned 32-bit integer required');
  let left=0, zeroes=0, best=0;
  for (let right=0;right<32;right++) {
    if (((number >>> right) & 1) === 0) zeroes++;
    while (zeroes > 1) { if (((number >>> left) & 1) === 0) zeroes--; left++; }
    best=Math.max(best,right-left+1);
  }
  return best;
}

