function robotPath(grid) {
  if (!Array.isArray(grid)) throw new TypeError('Grid required');
  if (!grid.length || !grid[0].length) return null;
  const rows=grid.length, cols=grid[0].length, previous=Array.from({length:rows},()=>Array(cols).fill(null));
  for (let r=0;r<rows;r++) for (let c=0;c<cols;c++) {
    if (!grid[r][c]) continue;
    if (r===0 && c===0) previous[r][c]=[-1,-1];
    else if (r>0 && previous[r-1][c]) previous[r][c]=[r-1,c];
    else if (c>0 && previous[r][c-1]) previous[r][c]=[r,c-1];
  }
  if (!previous[rows-1][cols-1]) return null;
  const path=[]; let r=rows-1,c=cols-1;
  while (r>=0) { path.push([r,c]); [r,c]=previous[r][c]; }
  return path.reverse();
}

