function longestIncreasingSubsequence(values) {
  if (!Array.isArray(values)) throw new TypeError('Array required');
  const tails=[], previous=Array(values.length).fill(-1);
  for (let i=0;i<values.length;i++) {
    let lo=0,hi=tails.length;
    while (lo<hi) { const mid=Math.floor((lo+hi)/2); if (values[tails[mid]]<values[i]) lo=mid+1; else hi=mid; }
    if (lo>0) previous[i]=tails[lo-1];
    tails[lo]=i;
  }
  const result=[];
