function matrixChainCost(matrices) {
  if (!Array.isArray(matrices)) throw new TypeError('Dimension pairs required');
  if (!matrices.length) return 0;
  for (let i=0;i<matrices.length;i++) {
    const [r,c]=matrices[i];
    if (!Number.isInteger(r) || !Number.isInteger(c) || r<=0 || c<=0 || (i>0 && matrices[i-1][1]!==r)) throw new RangeError('Compatible positive dimensions required');
  }
  const n=matrices.length, dp=Array.from({length:n},()=>Array(n).fill(0));
  for (let len=2;len<=n;len++) for (let i=0;i+len<=n;i++) {
    const j=i+len-1; dp[i][j]=Infinity;
    for (let k=i;k<j;k++) dp[i][j]=Math.min(dp[i][j],dp[i][k]+dp[k+1][j]+matrices[i][0]*matrices[k][1]*matrices[j][1]);
  }
  return dp[0][n-1];
}

function maxProfitWithTrades(prices, k) {
  if (prices == null || k == null) return null;
  if (!Array.isArray(prices) || !Number.isInteger(k)) throw new TypeError('Prices and integer k required');
  if (!prices.length || k<=0) return {profit:0,transactions:[]};
  const n=prices.length; k=Math.min(k,Math.floor(n/2));
  const dp=Array.from({length:k+1},()=>Array(n).fill(0));
  const buy=Array.from({length:k+1},()=>Array(n).fill(-1));
  for (let t=1;t<=k;t++) {
    let balance=-prices[0], buyDay=0;
    for (let day=1;day<n;day++) {
      dp[t][day]=dp[t][day-1];
      if (prices[day]+balance>dp[t][day]) { dp[t][day]=prices[day]+balance; buy[t][day]=buyDay; }
      const candidate=dp[t-1][day-1]-prices[day];
      if (candidate>balance) { balance=candidate; buyDay=day; }
    }
  }
  const transactions=[]; let t=k, day=n-1;
  while (t>0 && day>0) {
    if (buy[t][day]<0) { day--; continue; }
    const b=buy[t][day]; transactions.push({buy:b,sell:day}); day=b-1; t--;
  }
  return {profit:dp[k][n-1],transactions:transactions.reverse()};
}

