class QuickSort(object):

    def sort(self, data):
        if data is None:
            raise TypeError(&#x27;data cannot be None&#x27;)
        return self._sort(data)

    def _sort(self, data):
        if len(data) &lt; 2:
            return data
        equal = []
        left = []
        right = []
        pivot_index = len(data) // 2
        pivot_value = data[pivot_index]
        # Build the left and right partitions
        for item in data:
            if item == pivot_value:
                equal.append(item)
            elif item &lt; pivot_value:
                left.append(item)
            else:
                right.append(item)
        # Recursively apply quick_sort
        left_ = self._sort(left)
        right_ = self._sort(right)
        return left_ + equal + right_   Unit Test   %%writefile test_quick_sort.py
