function quickSort(values) {
  if (!Array.isArray(values)) throw new TypeError('Array required');
  if (values.length<2) return values.slice();
  const pivot=values[Math.floor(values.length/2)], low=[], equal=[], high=[];
  for (const value of values) (value<pivot ? low : value>pivot ? high : equal).push(value);
  return [...quickSort(low),...equal,...quickSort(high)];
