function radixSort(values) {
  if (!Array.isArray(values)) throw new TypeError('Array required');
  if (values.some(v=>!Number.isSafeInteger(v))) throw new TypeError('Safe integer elements required');
  function nonnegative(items) {
    let result=items.slice(), max=0;
    for (const value of result) max=Math.max(max,value);
    for (let place=1;place<=max;place*=10) {
      const buckets=Array.from({length:10},()=>[]);
      for (const value of result) buckets[Math.floor(value/place)%10].push(value);
      result=buckets.flat();
    }
    return result;
  }
  const negatives=nonnegative(values.filter(v=>v<0).map(v=>-v)).reverse().map(v=>-v);
  return negatives.concat(nonnegative(values.filter(v=>v>=0)));
}

