function searchRotated(values,target) {
  if (!Array.isArray(values)) throw new TypeError('Array required');
  let lo=0,hi=values.length-1;
  while (lo<=hi) {
    const mid=Math.floor((lo+hi)/2);
    if (values[mid]===target) return mid;
    if (values[lo]===values[mid] && values[mid]===values[hi]) { lo++; hi--; }
    else if (values[lo]<=values[mid]) {
      if (values[lo]<=target && target<values[mid]) hi=mid-1; else lo=mid+1;
    } else {
      if (values[mid]<target && target<=values[hi]) lo=mid+1; else hi=mid-1;
    }
  }
  return null;
}

