function searchMatrix(matrix,target) {
  if (!Array.isArray(matrix)) throw new TypeError('Matrix required');
  if (!matrix.length || !matrix[0].length) return null;
  let row=0,col=matrix[0].length-1;
  while (row<matrix.length && col>=0) {
