class Solution(object):

    def find_max_profit(self, prices):
        if prices is None:
            raise TypeError(&#x27;prices cannot be None&#x27;)
        if len(prices) &lt; 2:
            raise ValueError(&#x27;prices must have at least two values&#x27;)
