function nextSamePopcount(number) {
  if (typeof number !== 'bigint') throw new TypeError('BigInt required');
  if (number<=0n) throw new RangeError('Positive number required');
  const lowest=number & -number, ripple=number+lowest;
  const larger=ripple | (((ripple ^ number) >> 2n) / lowest);
  let copy=number, trailingOnes=0n, zeroes=0n;
  while ((copy & 1n) === 1n) { trailingOnes++; copy >>= 1n; }
  if (copy===0n) return {smaller:null,larger};
  while ((copy & 1n) === 0n) { zeroes++; copy >>= 1n; }
  const position=trailingOnes+zeroes;
  const cleared=(number >> (position+1n)) << (position+1n);
  const smaller=cleared | (((1n << (trailingOnes+1n))-1n) << (zeroes-1n));
  return {smaller,larger};
}

