  if (typeof note !== 'string' || typeof magazine !== 'string') throw new TypeError('Strings required');
  if (!note.length || !magazine.length) throw new RangeError('Nonempty strings required');
  const counts=new Map();
  for (const ch of magazine) counts.set(ch,(counts.get(ch)??0)+1);
  for (const ch of note) {
