def sentence_fits(words, rows, columns):
    if not isinstance(words, list) or any(not isinstance(w, str) or not w for w in words):
        raise TypeError(&quot;words must be a list of nonempty strings&quot;)
    if not isinstance(rows, int) or not isinstance(columns, int):
        raise TypeError(&quot;dimensions must be integers&quot;)
    if rows &lt; 0 or columns &lt; 0:
        raise ValueError(&quot;dimensions must be nonnegative&quot;)
    if not words or not rows or not columns or max(map(len, words)) &gt; columns:
        return 0
    transitions = {}
    next_word = completed = 0
    for _ in range(rows):
        if next_word not in transitions:
            cursor, used, cycles = next_word, 0, 0
            while used + len(words[cursor]) &lt;= columns:
                used += len(words[cursor]) + 1
                cursor += 1
                if cursor == len(words):
                    cursor = 0
                    cycles += 1
            transitions[next_word] = (cursor, cycles)
        next_word, cycles = transitions[next_word]
        completed += cycles
    return completed
