    &quot;link&quot;: &quot;https://foo.com&quot;,
},
{
    &quot;title&quot;: &quot;bar&#x27;s title&quot;,
    &quot;snippet&quot;: &quot;bar&#x27;s snippet&quot;,
    &quot;link&quot;: &quot;https://bar.com&quot;,
},
{
    &quot;title&quot;: &quot;baz&#x27;s title&quot;,
    &quot;snippet&quot;: &quot;baz&#x27;s snippet&quot;,
    &quot;link&quot;: &quot;https://baz.com&quot;,
},
