function budgetWindow(costs,budget) {
  let left=0, sum=0, best=[0,0];
  for (let right=0;right<costs.length;right++) {
    sum+=costs[right];
    while (sum>budget) sum-=costs[left++];
    if (right+1-left>best[1]-best[0]) best=[left,right+1];
  }
  return best;
}

