def device_groups(n,links):
    parent = list(range(n))
    size = [1] * n
    def find(x):
        while x != parent[x]:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for a,b in links:
        x,y = find(a),find(b)
        if x == y:
            continue
        if size[x] < size[y]:
            x,y = y,x
        parent[y] = x
        size[x] += size[y]
    groups = {}
    for i in range(n):
        groups.setdefault(find(i),[]).append(i)
    return list(groups.values())

