def min_capacity(costs,batches):
    if not isinstance(batches,int) or batches < 1:
        raise ValueError('invalid batch count')
    if not costs:
        return 0
    low,high = max(costs),sum(costs)
    def needed(cap):
        count,used = 1,0
        for cost in costs:
            if used+cost > cap:
                count += 1
                used = 0
            used += cost
        return count
    while low < high:
        mid = low+(high-low)//2
        if needed(mid) <= batches:
            high = mid
        else:
            low = mid+1
    return low

