function reverseKGroup(head, k) {
    const dummy = new ListNode(0, head);
    let pre = dummy;
    while(pre !== null){
        let cur = pre;
        for(let i = 0; i < k; i++){
            cur = cur?.next || null;
            if (cur === null) {
                return dummy.next;
            }
        }
        const node = pre.next;
        const nxt = cur?.next || null;
        cur.next = null;
        pre.next = reverse(node);
        node.next = nxt;
        pre = node;
    }
    return dummy.next;
}
function reverse(head) {
    let dummy = null;
    let cur = head;
    while(cur !== null){
        const nxt = cur.next;
        cur.next = dummy;
        dummy = cur;
        cur = nxt;
    }
    return dummy;
}

