function minSubArrayLen(target, nums) {
    const n = nums.length;
    const s = new Array(n + 1).fill(0);
    for(let i = 0; i < n; ++i){
        s[i + 1] = s[i] + nums[i];
    }
    let ans = n + 1;
    const search = (x)=>{
        let l = 0;
        let r = n + 1;
        while(l < r){
            const mid = l + r >>> 1;
            if (s[mid] >= x) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }
        return l;
    };
    for(let i = 0; i <= n; ++i){
        const j = search(s[i] + target);
        if (j <= n) {
            ans = Math.min(ans, j - i);
        }
    }
    return ans === n + 1 ? 0 : ans;
}

