    const m = matrix.length;
    const n = matrix[0].length;
    const f = Array(m).fill(0).map(()=>Array(n).fill(0));
    const dirs = [
        -1,
        0,
        1,
        0,
        -1
    ];
    const dfs = (i, j)=>{
        if (f[i][j] > 0) {
            return f[i][j];
        }
        for(let k = 0; k < 4; ++k){
            const x = i + dirs[k];
            const y = j + dirs[k + 1];
            if (x >= 0 && x < m && y >= 0 && y < n && matrix[x][y] > matrix[i][j]) {
                f[i][j] = Math.max(f[i][j], dfs(x, y));
            }
        }
        return ++f[i][j];
    };
    let ans = 0;
    for(let i = 0; i < m; ++i){
        for(let j = 0; j < n; ++j){
            ans = Math.max(ans, dfs(i, j));
        }
    }
    return ans;
}

