function guessNumber(n) {
    let l = 1;
    let r = n;
    while(l < r){
        const mid = l + r >>> 1;
        if (guess(mid) <= 0) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }
    return l;
}

