    d = new Map();
    q = [];
    constructor(){}
    insert(val) {
        if (this.d.has(val)) {
            return false;
        }
        this.d.set(val, this.q.length);
        this.q.push(val);
        return true;
    }
    remove(val) {
        if (!this.d.has(val)) {
            return false;
        }
        const i = this.d.get(val);
        this.d.set(this.q[this.q.length - 1], i);
        this.q[i] = this.q[this.q.length - 1];
        this.q.pop();
        this.d.delete(val);
        return true;
    }
    getRandom() {
        return this.q[Math.floor(Math.random() * this.q.length)];
    }
}

