class MyCircularQueue {
    queue;
    left;
    right;
    capacity;
    constructor(k){
        this.queue = new Array(k);
        this.left = 0;
        this.right = 0;
        this.capacity = k;
    }
    enQueue(value) {
        if (this.isFull()) {
            return false;
        }
        this.queue[this.right % this.capacity] = value;
        this.right++;
        return true;
    }
    deQueue() {
        if (this.isEmpty()) {
            return false;
        }
        this.left++;
        return true;
    }
    Front() {
        if (this.isEmpty()) {
            return -1;
        }
        return this.queue[this.left % this.capacity];
    }
    Rear() {
        if (this.isEmpty()) {
            return -1;
        }
        return this.queue[(this.right - 1) % this.capacity];
    }
    isEmpty() {
        return this.right - this.left === 0;
    }
    isFull() {
        return this.right - this.left === this.capacity;
    }
}

