function maxProfit(prices, fee) {
    const n = prices.length;
    const f = Array.from({
        length: n
    }, ()=>[
            -1,
            -1
        ]);
    const dfs = (i, j)=>{
        if (i >= n) {
            return 0;
        }
        if (f[i][j] !== -1) {
            return f[i][j];
        }
        let ans = dfs(i + 1, j);
        if (j) {
            ans = Math.max(ans, prices[i] + dfs(i + 1, 0) - fee);
        } else {
            ans = Math.max(ans, -prices[i] + dfs(i + 1, 1));
        }
        return f[i][j] = ans;
    };
    return dfs(0, 0);
}

