function minEatingSpeed(piles, h) {
    let [l, r] = [
        1,
        Math.max(...piles)
    ];
    while(l < r){
        const mid = l + r >> 1;
        const s = piles.map((x)=>Math.ceil(x / mid)).reduce((a, b)=>a + b);
        if (s <= h) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }
    return l;
}

