        for (const x of q){
            if (x === m) {
                return ans;
            }
            for(let y = x + 1; y <= Math.min(x + 6, m); y++){
                let i = Math.floor((y - 1) / n);
                let j = (y - 1) % n;
                if (i % 2 === 1) {
