    }
    for(let i = n - 1; ~i; --i){
        if (nums[i]) {
            right[i] = right[i + 1] + 1;
        }
    }
    let ans = 0;
    for(let i = 0; i < n; ++i){
        ans = Math.max(ans, left[i] + right[i + 1]);
    }
    return ans;
}

